);

-- indexes (each leads with company_no: every query runs inside one company)
CREATE INDEX idx_activity_log_entity ON activity_log (company_no, entity, entity_id);
CREATE INDEX idx_activity_log_time ON activity_log (company_no, created_at);
CREATE INDEX idx_approval_requester ON approval_requests (company_no, requested_by, id);
CREATE INDEX idx_approval_status ON approval_requests (company_no, status, id);
CREATE UNIQUE INDEX uq_approval_rules_name ON approval_rules (company_no, lower(name));
CREATE INDEX idx_auth_sessions_user ON auth_sessions (company_no, user_id, revoked_at);
CREATE INDEX idx_bank_history_ledger ON bank_recon_history (company_no, bank_ledger_id, id);
CREATE UNIQUE INDEX idx_bank_imports_file ON bank_statement_imports (company_no, bank_ledger_id, file_hash);
CREATE INDEX idx_bank_lines_entry ON bank_statement_lines (company_no, matched_entry_id);
CREATE INDEX idx_bank_lines_hash ON bank_statement_lines (company_no, bank_ledger_id, dedupe_hash);
CREATE INDEX idx_bank_lines_import ON bank_statement_lines (company_no, import_id, status);
CREATE INDEX idx_batch_alloc_entry ON batch_allocations (company_no, inventory_entry_id);
CREATE INDEX idx_batch_alloc_item ON batch_allocations (company_no, stock_item_id, batch_no);
CREATE INDEX idx_bill_allocations_ldg ON bill_allocations (company_no, ledger_id);
CREATE INDEX idx_bill_allocations_vch ON bill_allocations (company_no, voucher_id);
CREATE UNIQUE INDEX uq_branches_name ON branches (company_no, lower(name));
CREATE UNIQUE INDEX idx_budgets_unique ON budgets (company_no, ledger_id, COALESCE(department_id, 0), COALESCE(branch_id, 0), period_type, period_start);
CREATE UNIQUE INDEX uq_departments_name ON departments (company_no, lower(name));
CREATE UNIQUE INDEX idx_godowns_code ON godowns (company_no, code);
CREATE INDEX idx_import_batches_hash ON import_batches (company_no, file_hash, status);
CREATE INDEX idx_inv_docs_kind ON inv_docs (company_no, kind, id);
CREATE INDEX idx_inv_order_docs_voucher ON inv_order_docs (company_no, voucher_id);
CREATE INDEX idx_inv_order_docs_order ON inv_order_docs (company_no, order_id);
CREATE INDEX idx_inv_order_lines_order ON inv_order_lines (company_no, order_id);
CREATE INDEX idx_inv_orders_portal ON inv_orders (company_no, portal_user_id, id);
CREATE INDEX idx_inv_orders_party ON inv_orders (company_no, party_ledger_id, id);
CREATE INDEX idx_inv_orders_kind ON inv_orders (company_no, kind, status, id);
CREATE INDEX idx_inv_reservations_ref ON inv_reservations (company_no, ref_type, ref_id);
CREATE INDEX idx_inv_reservations_item ON inv_reservations (company_no, item_id, godown_id);
CREATE INDEX idx_inventory_entries_item_godown ON inventory_entries (company_no, stock_item_id, godown_id);
CREATE INDEX idx_inventory_entries_item ON inventory_entries (company_no, stock_item_id);
CREATE INDEX idx_inventory_entries_vch ON inventory_entries (company_no, voucher_id);
CREATE INDEX idx_ledger_entries_ldg ON ledger_entries (company_no, ledger_id);
CREATE INDEX idx_ledger_entries_vch ON ledger_entries (company_no, voucher_id);
CREATE INDEX idx_notifications_state ON notifications (company_no, is_resolved, is_read);
CREATE INDEX idx_password_resets_user ON password_resets (company_no, user_id, used_at);
CREATE INDEX idx_quotation_followups_q ON quotation_followups (company_no, quotation_id);
CREATE INDEX idx_quotation_items_q ON quotation_items (company_no, quotation_id);
CREATE INDEX idx_quotations_followup ON quotations (company_no, next_followup_date);
CREATE INDEX idx_quotations_status ON quotations (company_no, status);
CREATE INDEX idx_quotations_date ON quotations (company_no, date);
CREATE INDEX idx_recurring_drafts_status ON recurring_drafts (company_no, status, due_date);
CREATE INDEX idx_recurring_due ON recurring_templates (company_no, is_active, next_due);
CREATE INDEX idx_report_outputs_sched ON report_outputs (company_no, schedule_id, id);
CREATE INDEX idx_sched_due ON scheduled_reports (company_no, is_active, next_run_at);
CREATE UNIQUE INDEX uq_serial_numbers_stock_item_id_serial_no ON serial_numbers (company_no, stock_item_id, lower(serial_no));
CREATE INDEX idx_serial_status ON serial_numbers (company_no, stock_item_id, status);
CREATE UNIQUE INDEX idx_stock_items_sku ON stock_items (company_no, sku);
CREATE UNIQUE INDEX idx_stock_items_barcode ON stock_items (company_no, lower(barcode)) WHERE barcode IS NOT NULL AND barcode <> '';
CREATE INDEX idx_user_logins_time ON user_logins (company_no, login_time);
CREATE INDEX idx_user_logins_user ON user_logins (company_no, user_id);
CREATE UNIQUE INDEX uq_users_username ON users (company_no, lower(username));
CREATE INDEX idx_users_email ON users (company_no, lower(email));
CREATE INDEX idx_users_party ON users (company_no, party_id);
CREATE INDEX idx_attachments_voucher ON voucher_attachments (company_no, voucher_id);
CREATE INDEX idx_vouchers_department ON vouchers (company_no, department_id);
CREATE INDEX idx_vouchers_branch ON vouchers (company_no, branch_id);
CREATE INDEX idx_vouchers_no ON vouchers (company_no, voucher_no);
CREATE INDEX idx_vouchers_type ON vouchers (company_no, voucher_type);
CREATE INDEX idx_vouchers_date ON vouchers (company_no, date);

-- foreign keys: (company_no, column) -> (company_no, key), so a row can never point into another company
ALTER TABLE account_groups ADD CONSTRAINT fk_account_groups_parent_id FOREIGN KEY (company_no, parent_id) REFERENCES account_groups (company_no, id) DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE bank_reconciliation ADD CONSTRAINT fk_bank_reconciliation_ledger_entry_id FOREIGN KEY (company_no, ledger_entry_id) REFERENCES ledger_entries (company_no, id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE bank_statement_imports ADD CONSTRAINT fk_bank_statement_imports_bank_ledger_id FOREIGN KEY (company_no, bank_ledger_id) REFERENCES ledgers (company_no, id) DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE bank_statement_lines ADD CONSTRAINT fk_bank_statement_lines_matched_entry_id FOREIGN KEY (company_no, matched_entry_id) REFERENCES ledger_entries (company_no, id) ON DELETE SET NULL (matched_entry_id) DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE bank_statement_lines ADD CONSTRAINT fk_bank_statement_lines_import_id FOREIGN KEY (company_no, import_id) REFERENCES bank_statement_imports (company_no, id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE batch_allocations ADD CONSTRAINT fk_batch_allocations_stock_item_id FOREIGN KEY (company_no, stock_item_id) REFERENCES stock_items (company_no, id) DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE batch_allocations ADD CONSTRAINT fk_batch_allocations_inventory_entry_id FOREIGN KEY (company_no, inventory_entry_id) REFERENCES inventory_entries (company_no, id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE bill_allocations ADD CONSTRAINT fk_bill_allocations_ledger_id FOREIGN KEY (company_no, ledger_id) REFERENCES ledgers (company_no, id) DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE bill_allocations ADD CONSTRAINT fk_bill_allocations_voucher_id FOREIGN KEY (company_no, voucher_id) REFERENCES vouchers (company_no, id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE budgets ADD CONSTRAINT fk_budgets_ledger_id FOREIGN KEY (company_no, ledger_id) REFERENCES ledgers (company_no, id) DEFERRABLE INITIALLY IMMEDIATE;
